#include <stdio.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>
#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

#define st first
#define nd second
#define read(x) scanf("%d", &(x))
#define MAXN 1000005

typedef long long int64;

int a[MAXN], cnt[301];

int main(int argc, char const* argv[]) {
    if (argc == 3) {
        freopen(argv[1], "r", stdin);
        freopen(argv[2], "w", stdout);
    }

    int n;
    read(n);

    int x = 0, mn = 301, nb = 0;
    for (int i = 0; i < n; ++i) {
        read(a[i]);
        x ^= a[i];
        mn = min(a[i], mn);
        if (cnt[a[i]] == 0) {
            ++nb;
        }
        ++cnt[a[i]];
    }

    if (nb == 1 || x % 2 == 0) {
        puts("BitLGM");
        return 0;
    }

    x = 0;
    for (int i = 0; i < n; ++i) {
        a[i] -= mn;
        x ^= a[i];
    }

    if (x % 2 == 1) {
        puts("BitLGM");
    } else {
        puts("BitAryo");
    }

    return 0;
}

